/**
 * Price Split Formatter
 * node starter/index.js
 */

const readline = require("node:readline");

function main() {
  const lines = [];
  const rl = readline.createInterface({ input: process.stdin });

  rl.on("line", (line) => {
    lines.push(line);
    if (lines.length < 2) return;

//Main extraction

let total=Number(lines[0].trim());
let people=Number(lines[1].trim());
let rate = total / people;
let formattedOutput = ""

if (!Number.isFinite(rate) || !people > 0 || !total > 0 ) {
formattedOutput = "ERROR: invalid number";
}
else{
formattedOutput = `Share: $${rate.toFixed(2)}`
}
    process.stdout.write(formattedOutput);
    rl.close();
  });
}

main();

